import{_ as t,c as a,o,al as s}from"./chunks/framework.DM883ANZ.js";const h=JSON.parse('{"title":"Message Rates","description":"Message Rates — MAVLink message, enum and command reference.","frontmatter":{"head":[["meta",{"property":"og:title","content":"Message Rates"}],["meta",{"property":"og:description","content":"Message Rates — MAVLink message, enum and command reference."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:url","content":"https://mavlink.io/zh/guide/message_rates.html"}],["link",{"rel":"canonical","href":"https://mavlink.io/zh/guide/message_rates.html"}]]},"headers":[],"relativePath":"zh/guide/message_rates.md","filePath":"zh/guide/message_rates.md","lastUpdated":1789005790000}'),n={name:"zh/guide/message_rates.md"};function r(i,e,d,c,l,m){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="message-rates" tabindex="-1">Message Rates <a class="header-anchor" href="#message-rates" aria-label="Permalink to &quot;Message Rates&quot;">​</a></h1><p><a href="./../messages/common.html#MAV_CMD_SET_MESSAGE_INTERVAL">MAV_CMD_SET_MESSAGE_INTERVAL</a> can be used to dynamically set the message streaming rates of a MAVLink component, provided the protocol is supported at both ends. This is mainly useful over unpredictable links, such as the telemetry link to a GCS, where the required message streams depend on the particular GCS in use, and channel quality depends on distance and the radio used.</p><p>This section provides guidance on configuring MAVLink message rates using the <code>MAV_CMD_SET_MESSAGE_INTERVAL</code> command.</p><h2 id="configuring-message-rates" tabindex="-1">Configuring Message Rates <a class="header-anchor" href="#configuring-message-rates" aria-label="Permalink to &quot;Configuring Message Rates&quot;">​</a></h2><p><code>MAV_CMD_SET_MESSAGE_INTERVAL</code> can be used to increase or decrease the rate of individual messages for QoS management — for example, reducing unnecessary telemetry on a bandwidth-constrained link, or increasing the rate of a specific message needed by a companion computer.</p><p>The interval set by this command only applies to the link (connection) the command was received on. To configure rates on a specific serial port, send the command over that port.</p><p>To silence a message, set <code>param2</code> (interval in microseconds) to <code>-1</code>. To restore the default rate, set the interval to <code>0</code>.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Flight stacks commonly use parameters to set default streaming rates, which are then overridden by <code>MAV_CMD_SET_MESSAGE_INTERVAL</code>. On ArduPilot, these are <code>MAVn_*</code> parameters. On PX4 these are <code>MAV_*_RATE</code> parameters.</p></div><h3 id="example-configuration" tabindex="-1">Example Configuration <a class="header-anchor" href="#example-configuration" aria-label="Permalink to &quot;Example Configuration&quot;">​</a></h3><p>Disable a pair of IMU sensor messages, and request <code>RAW_IMU</code> at 200 Hz:</p><table tabindex="0"><thead><tr><th>消息</th><th>Interval (us)</th><th>备注</th></tr></thead><tbody><tr><td><code>RAW_IMU</code> (id: 27)</td><td>5000</td><td>200 Hz for EKF input</td></tr><tr><td><code>SCALED_IMU2</code> (id: 116)</td><td>-1</td><td>Disabled</td></tr><tr><td><code>HIGHRES_IMU</code> (id: 105)</td><td>-1</td><td>Disabled</td></tr></tbody></table><h2 id="streaming-to-the-autopilot" tabindex="-1">Streaming to the Autopilot <a class="header-anchor" href="#streaming-to-the-autopilot" aria-label="Permalink to &quot;Streaming to the Autopilot&quot;">​</a></h2><p><code>MAV_CMD_SET_MESSAGE_INTERVAL</code> should be used to control streaming rates, if supported, when streaming unpredictable content over unreliable links.</p><p>When using predictable links with a predictable endpoint, such as a companion computer, it is more usual to hard code the streaming rates and messages sent. For example, <code>VISION_POSITION_ESTIMATE</code> would be sent at a fixed rate because the link to the companion computer is usually a high-speed serial/Ethernet link.</p><h2 id="implementations" tabindex="-1">Implementations <a class="header-anchor" href="#implementations" aria-label="Permalink to &quot;Implementations&quot;">​</a></h2><p>Supported on PX4 v1.11+ and ArduPilot v4.0+. Behavior on older versions of these two autopilots is undefined.</p>',16)])])}const u=t(n,[["render",r]]);export{h as __pageData,u as default};
